import { Switch, Route } from "wouter";
import PageTransition from "@/components/PageTransition";
import { queryClient } from "./lib/queryClient";
import { QueryClientProvider } from "@tanstack/react-query";
import { Toaster } from "@/components/ui/toaster";
import { TooltipProvider } from "@/components/ui/tooltip";
import { ThemeProvider } from "@/components/ThemeProvider";
import SplashScreen from "@/components/SplashScreen";
import { useEffect, useState } from "react";
import { useLocation } from "wouter";
import NotFound from "@/pages/not-found";
import Landing from "@/pages/Landing";
import Login from "@/pages/Login";
import Register from "@/pages/Register";
import EmailVerification from "@/pages/EmailVerification";
import VerifyCode from "@/pages/VerifyCode";
import VerifySuccess from "@/pages/VerifySuccess";
import Dashboard from "@/pages/Dashboard";
import TrackCustomer from "@/pages/TrackCustomer";
import AllOrders from "@/pages/AllOrders";
import Wallet from "@/pages/Wallet";
import Settings from "@/pages/Settings";
import AdminOptions from "@/pages/AdminOptions";
import FaceVerification from "@/pages/FaceVerification";

function Router() {
  return (
    <PageTransition>
      <Switch>
        <Route path="/" component={Landing} />
        <Route path="/login" component={Login} />
        <Route path="/register" component={Register} />
        <Route path="/email-verification" component={EmailVerification} />
        <Route path="/verify-code" component={VerifyCode} />
        <Route path="/verify-success" component={VerifySuccess} />
        <Route path="/face-verification" component={FaceVerification} />
        <Route path="/dashboard" component={Dashboard} />
        <Route path="/track-customer/:id" component={TrackCustomer} />
        <Route path="/orders" component={AllOrders} />
        <Route path="/wallet" component={Wallet} />
        <Route path="/settings" component={Settings} />
        <Route path="/admin/options" component={AdminOptions} />
        <Route component={NotFound} />
      </Switch>
    </PageTransition>
  );
}

function App() {
  const [showSplash, setShowSplash] = useState(true);
  const [, setLocation] = useLocation();

  useEffect(() => {
    const MIN_SPLASH_MS = 8000; // sesuai permintaan: 8 detik
    const sources = [
      "/splash-brand.png",
      "/splash-top.png",
      "/splash-bottom.png",
    ];

    const preload = sources.map(
      (src) =>
        new Promise<void>((resolve) => {
          const img = new Image();
          img.onload = () => resolve();
          img.onerror = () => resolve(); // jangan blok kalau gagal
          img.src = src;
        })
    );

    const minTimer = new Promise<void>((resolve) =>
      setTimeout(() => resolve(), MIN_SPLASH_MS)
    );

    Promise.all([minTimer, ...preload]).then(() => {
      setShowSplash(false);
      // setelah splash selesai, arahkan ke login jika masih di root
      if (window.location.pathname === "/") {
        setLocation("/login");
      }
    });
  }, []);

  return (
    <QueryClientProvider client={queryClient}>
      <ThemeProvider>
        <TooltipProvider>
          <Toaster />
          <SplashScreen show={showSplash} />
          <Router />
        </TooltipProvider>
      </ThemeProvider>
    </QueryClientProvider>
  );
}

export default App;

