import { useQuery, useMutation } from "@tanstack/react-query";
import { queryClient, apiRequest } from "@/lib/queryClient";
import type { Wallet, Transaction } from "@shared/schema";

export function useWallet(driverId: string) {
  return useQuery<Wallet>({
    queryKey: ["/api/wallet", driverId],
    queryFn: async () => {
      const response = await fetch(`/api/wallet/driver/${driverId}`);
      if (!response.ok) throw new Error("Failed to fetch wallet");
      return response.json();
    },
    enabled: !!driverId,
  });
}

export function useTransactions(driverId: string) {
  return useQuery<Transaction[]>({
    queryKey: ["/api/transactions", driverId],
    queryFn: async () => {
      const response = await fetch(`/api/transactions/driver/${driverId}`);
      if (!response.ok) throw new Error("Failed to fetch transactions");
      return response.json();
    },
    enabled: !!driverId,
  });
}

export function useWithdraw() {
  return useMutation({
    mutationFn: async ({
      driverId,
      amount,
      paymentMethod,
    }: {
      driverId: string;
      amount: string;
      paymentMethod: string;
    }) => {
      return apiRequest("POST", "/api/wallet/withdraw", { driverId, amount, paymentMethod });
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ["/api/wallet", variables.driverId] });
      queryClient.invalidateQueries({ queryKey: ["/api/transactions", variables.driverId] });
    },
  });
}

