import type { Express, Request } from "express";
import { createServer, type Server } from "http";
import { storage } from "./storage";
import { randomBytes } from "crypto";
import { 
  registrationStep1Schema, 
  registrationStep2Schema,
  loginSchema,
  emailVerificationSchema,
  otpVerificationSchema,
  optionBankSchema,
  optionWorkingHourSchema,
  countryQuerySchema,
} from "@shared/schema";

export async function registerRoutes(app: Express): Promise<Server> {
  // ===== Google OAuth state store =====
  const oauthStates = new Map<string, number>();
  const OAUTH_STATE_TTL_MS = 10 * 60 * 1000; // 10 minutes

  const GOOGLE_CLIENT_ID = process.env.GOOGLE_CLIENT_ID;
  const GOOGLE_CLIENT_SECRET = process.env.GOOGLE_CLIENT_SECRET;

  const getBaseUrl = (req: Request) => {
    const proto = req.headers["x-forwarded-proto"]?.toString() || req.protocol;
    const host = req.get("host") || `localhost:${process.env.PORT || "5000"}`;
    return `${proto}://${host}`;
  };

  const generateState = () => {
    const state = randomBytes(16).toString("hex");
    oauthStates.set(state, Date.now());
    return state;
  };

  const consumeState = (state: string) => {
    const ts = oauthStates.get(state);
    if (!ts) return false;
    oauthStates.delete(state);
    return Date.now() - ts < OAUTH_STATE_TTL_MS;
  };

  // Health check
  app.get("/api/health", (_req, res) => {
    res.json({ ok: true, timestamp: new Date().toISOString() });
  });

  // ========== Authentication Routes ==========

  // Login
  app.post("/api/auth/login", async (req, res) => {
    try {
      const { emailOrPhone, password } = loginSchema.parse(req.body);

      const driver = await storage.getDriverByEmailOrPhone(emailOrPhone);

      if (!driver || driver.password !== password) {
        return res.status(401).json({ 
          error: "Invalid credentials" 
        });
      }

      // In production, use proper session management
      res.json({
        success: true,
        driver: {
          id: driver.id,
          fullName: driver.fullName,
          email: driver.email,
          isEmailVerified: driver.isEmailVerified
        }
      });
    } catch (error) {
      res.status(400).json({ error: "Invalid request" });
    }
  });

  // Register Step 1 & 2 (Combined)
  app.post("/api/auth/register", async (req, res) => {
    try {
      const { step1, step2 } = req.body;

      // Validate both steps
      const step1Data = registrationStep1Schema.parse(step1);
      const step2Data = registrationStep2Schema.parse(step2);

      // Check if email already exists
      const existingDriver = await storage.getDriverByEmail(step1Data.email);
      if (existingDriver) {
        return res.status(400).json({ 
          error: "Email already registered" 
        });
      }

      // Create driver
      const driver = await storage.createDriver({
        fullName: step1Data.fullName,
        email: step1Data.email,
        phoneNumber: step1Data.phoneNumber,
        password: step1Data.password,
        country: step2Data.country,
        idCardNumber: step2Data.idCardNumber,
        address: step2Data.address,
        workingHours: step2Data.workingHours,
        bankName: step2Data.bankName,
        accountHolderName: step2Data.accountHolderName,
        accountNumber: step2Data.accountNumber,
        preferredPaymentMethod: step2Data.preferredPaymentMethod,
        secondaryContactNumber: step2Data.secondaryContactNumber || null,
      });

      res.json({
        success: true,
        driver: {
          id: driver.id,
          email: driver.email
        }
      });
    } catch (error) {
      res.status(400).json({ error: "Invalid registration data" });
    }
  });

  // Country-based options (banks, working hours)
  app.get("/api/options", async (req, res) => {
    try {
      const { country } = countryQuerySchema.parse({ country: req.query.country });
      const options = await storage.getOptions(country);
      res.json({
        country,
        bankOptions: options?.banks || [],
        workingHoursOptions: options?.workingHours || [],
      });
    } catch (error) {
      res.status(400).json({ error: "Invalid request" });
    }
  });

  // ======= Admin Country Options (CRUD) =======
  // List supported countries
  app.get("/api/admin/countries", async (_req, res) => {
    try {
      const countries = await storage.listCountries();
      res.json({ countries });
    } catch (error) {
      res.status(400).json({ error: "Invalid request" });
    }
  });

  // Add a bank to a country
  app.post("/api/admin/options/banks", async (req, res) => {
    try {
      const { country } = countryQuerySchema.parse({ country: req.query.country });
      const { name } = optionBankSchema.parse(req.body);
      const options = await storage.addBank(country, name);
      res.json({ country, ...options });
    } catch (error) {
      res.status(400).json({ error: "Invalid request" });
    }
  });

  // Remove a bank from a country
  app.delete("/api/admin/options/banks", async (req, res) => {
    try {
      const { country } = countryQuerySchema.parse({ country: req.query.country });
      const { name } = optionBankSchema.parse(req.body);
      const options = await storage.removeBank(country, name);
      res.json({ country, ...options });
    } catch (error) {
      res.status(400).json({ error: "Invalid request" });
    }
  });

  // Add a working hour to a country
  app.post("/api/admin/options/working-hours", async (req, res) => {
    try {
      const { country } = countryQuerySchema.parse({ country: req.query.country });
      const { value } = optionWorkingHourSchema.parse(req.body);
      const options = await storage.addWorkingHour(country, value);
      res.json({ country, ...options });
    } catch (error) {
      res.status(400).json({ error: "Invalid request" });
    }
  });

  // Remove a working hour from a country
  app.delete("/api/admin/options/working-hours", async (req, res) => {
    try {
      const { country } = countryQuerySchema.parse({ country: req.query.country });
      const { value } = optionWorkingHourSchema.parse(req.body);
      const options = await storage.removeWorkingHour(country, value);
      res.json({ country, ...options });
    } catch (error) {
      res.status(400).json({ error: "Invalid request" });
    }
  });

  // Send verification code
  app.post("/api/auth/send-verification", async (req, res) => {
    try {
      const { email } = emailVerificationSchema.parse(req.body);

      // In production, send actual email
      // For now, just return success
      res.json({
        success: true,
        message: "Verification code sent"
      });
    } catch (error) {
      res.status(400).json({ error: "Invalid email" });
    }
  });

  // Verify code
  app.post("/api/auth/verify-code", async (req, res) => {
    try {
      const { code, email } = req.body;

      // In production, verify actual OTP
      // For now, accept any 4-digit code
      if (code.length === 4) {
        // Update driver verification status
        const driver = await storage.getDriverByEmail(email);
        if (driver) {
          await storage.updateDriver(driver.id, { isEmailVerified: true });
        }

        res.json({
          success: true,
          message: "Email verified successfully"
        });
      } else {
        res.status(400).json({ error: "Invalid verification code" });
      }
    } catch (error) {
      res.status(400).json({ error: "Invalid request" });
    }
  });

  // ======= Google OAuth =======
  // Generate Google OAuth URL (safe for frontend fetch)
  app.get("/api/auth/google/url", (req, res) => {
    try {
      if (!GOOGLE_CLIENT_ID || !GOOGLE_CLIENT_SECRET) {
        return res.status(500).json({ error: "Google OAuth is not configured" });
      }

      const baseUrl = getBaseUrl(req);
      const redirectUri = `${baseUrl}/api/auth/google/callback`;
      const state = generateState();

      const params = new URLSearchParams({
        client_id: GOOGLE_CLIENT_ID,
        redirect_uri: redirectUri,
        response_type: "code",
        scope: "openid email profile",
        state,
        prompt: "select_account",
        access_type: "offline",
      });

      const url = `https://accounts.google.com/o/oauth2/v2/auth?${params.toString()}`;
      res.json({ url });
    } catch (err) {
      res.status(500).json({ error: "Failed to generate Google OAuth URL" });
    }
  });

  // Redirect helper (optional)
  app.get("/api/auth/google", (req, res) => {
    if (!GOOGLE_CLIENT_ID || !GOOGLE_CLIENT_SECRET) {
      return res.status(500).json({ error: "Google OAuth is not configured" });
    }
    const baseUrl = getBaseUrl(req);
    const redirectUri = `${baseUrl}/api/auth/google/callback`;
    const state = generateState();
    const params = new URLSearchParams({
      client_id: GOOGLE_CLIENT_ID,
      redirect_uri: redirectUri,
      response_type: "code",
      scope: "openid email profile",
      state,
      prompt: "select_account",
      access_type: "offline",
    });
    const url = `https://accounts.google.com/o/oauth2/v2/auth?${params.toString()}`;
    res.redirect(url);
  });

  // OAuth callback
  app.get("/api/auth/google/callback", async (req, res) => {
    try {
      if (!GOOGLE_CLIENT_ID || !GOOGLE_CLIENT_SECRET) {
        return res.status(500).send("Google OAuth is not configured");
      }
      const { code, state } = req.query as { code?: string; state?: string };
      if (!code || !state) {
        return res.status(400).send("Missing code or state");
      }
      if (!consumeState(state)) {
        return res.status(400).send("Invalid state");
      }

      const baseUrl = getBaseUrl(req);
      const redirectUri = `${baseUrl}/api/auth/google/callback`;

      // Exchange code for tokens
      const tokenResp = await fetch("https://oauth2.googleapis.com/token", {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({
          code,
          client_id: GOOGLE_CLIENT_ID,
          client_secret: GOOGLE_CLIENT_SECRET,
          redirect_uri: redirectUri,
          grant_type: "authorization_code",
        }),
      });

      if (!tokenResp.ok) {
        const text = await tokenResp.text();
        return res.status(400).send(`Token exchange failed: ${text}`);
      }

      const tokenJson = await tokenResp.json() as any;
      const idToken = tokenJson.id_token as string | undefined;
      if (!idToken) {
        return res.status(400).send("Missing id_token");
      }

      // Verify id_token via Google tokeninfo (simpler, no extra deps)
      const verifyResp = await fetch(
        `https://oauth2.googleapis.com/tokeninfo?id_token=${encodeURIComponent(idToken)}`
      );
      if (!verifyResp.ok) {
        const text = await verifyResp.text();
        return res.status(400).send(`Token verify failed: ${text}`);
      }
      const claims = await verifyResp.json() as any;
      if (claims.aud !== GOOGLE_CLIENT_ID) {
        return res.status(400).send("Invalid token audience");
      }

      const email: string | undefined = claims.email;
      const emailVerified: boolean = claims.email_verified === true || claims.email_verified === "true";
      const name: string | undefined = claims.name;

      if (!email || !emailVerified) {
        return res.status(400).send("Email not available or not verified");
      }

      let driver = await storage.getDriverByEmail(email);
      if (!driver) {
        driver = await storage.createDriver({
          fullName: name || email,
          email,
          phoneNumber: "0000000000",
          password: "oauth-google",
        });
      }
      // Ensure email marked verified
      await storage.updateDriver(driver.id, { isEmailVerified: true });

      // Redirect to dashboard with query so SPA can persist
      const redirectTo = `/dashboard?driverId=${encodeURIComponent(driver.id)}&email=${encodeURIComponent(driver.email)}`;
      res.redirect(redirectTo);
    } catch (err) {
      res.status(500).send("Unexpected error during Google OAuth");
    }
  });

  // ========== Driver Routes ==========

  // Get driver profile
  app.get("/api/driver/:id", async (req, res) => {
    try {
      const { id } = req.params;
      const driver = await storage.getDriver(id);

      if (!driver) {
        return res.status(404).json({ error: "Driver not found" });
      }

      res.json(driver);
    } catch (error) {
      res.status(400).json({ error: "Invalid request" });
    }
  });

  // Update driver profile
  app.patch("/api/driver/:id", async (req, res) => {
    try {
      const { id } = req.params;
      const updates = req.body;

      const driver = await storage.updateDriver(id, updates);

      if (!driver) {
        return res.status(404).json({ error: "Driver not found" });
      }

      res.json(driver);
    } catch (error) {
      res.status(400).json({ error: "Invalid request" });
    }
  });

  // ========== Order Routes ==========

  // Get all orders
  app.get("/api/orders", async (req, res) => {
    try {
      const { status, driverId } = req.query;

      let orders;
      if (status) {
        orders = await storage.getOrdersByStatus(status as string);
      } else if (driverId) {
        orders = await storage.getOrdersByDriver(driverId as string);
      } else {
        orders = await storage.getAllOrders();
      }

      res.json(orders);
    } catch (error) {
      res.status(400).json({ error: "Invalid request" });
    }
  });

  // Get single order
  app.get("/api/orders/:id", async (req, res) => {
    try {
      const { id } = req.params;
      const order = await storage.getOrder(id);

      if (!order) {
        return res.status(404).json({ error: "Order not found" });
      }

      res.json(order);
    } catch (error) {
      res.status(400).json({ error: "Invalid request" });
    }
  });

  // Create order
  app.post("/api/orders", async (req, res) => {
    try {
      const order = await storage.createOrder(req.body);
      res.json(order);
    } catch (error) {
      res.status(400).json({ error: "Invalid order data" });
    }
  });

  // Update order (accept, cancel, etc.)
  app.patch("/api/orders/:id", async (req, res) => {
    try {
      const { id } = req.params;
      const updates = req.body;

      const order = await storage.updateOrder(id, updates);

      if (!order) {
        return res.status(404).json({ error: "Order not found" });
      }

      res.json(order);
    } catch (error) {
      res.status(400).json({ error: "Invalid request" });
    }
  });

  // Accept order
  app.post("/api/orders/:id/accept", async (req, res) => {
    try {
      const { id } = req.params;
      const { driverId } = req.body;

      const order = await storage.updateOrder(id, {
        status: "active",
        driverId
      });

      if (!order) {
        return res.status(404).json({ error: "Order not found" });
      }

      res.json(order);
    } catch (error) {
      res.status(400).json({ error: "Invalid request" });
    }
  });

  // Cancel order
  app.post("/api/orders/:id/cancel", async (req, res) => {
    try {
      const { id } = req.params;

      const order = await storage.updateOrder(id, {
        status: "canceled"
      });

      if (!order) {
        return res.status(404).json({ error: "Order not found" });
      }

      res.json(order);
    } catch (error) {
      res.status(400).json({ error: "Invalid request" });
    }
  });

  // Complete order
  app.post("/api/orders/:id/complete", async (req, res) => {
    try {
      const { id } = req.params;

      const order = await storage.updateOrder(id, {
        status: "completed"
      });

      if (!order) {
        return res.status(404).json({ error: "Order not found" });
      }

      res.json(order);
    } catch (error) {
      res.status(400).json({ error: "Invalid request" });
    }
  });

  // ========== Wallet Routes ==========

  // Get wallet by driver
  app.get("/api/wallet/driver/:driverId", async (req, res) => {
    try {
      const { driverId } = req.params;
      const wallet = await storage.getWalletByDriver(driverId);

      if (!wallet) {
        return res.status(404).json({ error: "Wallet not found" });
      }

      res.json(wallet);
    } catch (error) {
      res.status(400).json({ error: "Invalid request" });
    }
  });

  // Update wallet
  app.patch("/api/wallet/:id", async (req, res) => {
    try {
      const { id } = req.params;
      const updates = req.body;

      const wallet = await storage.updateWallet(id, updates);

      if (!wallet) {
        return res.status(404).json({ error: "Wallet not found" });
      }

      res.json(wallet);
    } catch (error) {
      res.status(400).json({ error: "Invalid request" });
    }
  });

  // Create withdrawal
  app.post("/api/wallet/withdraw", async (req, res) => {
    try {
      const { driverId, amount, paymentMethod } = req.body;

      // Get wallet
      const wallet = await storage.getWalletByDriver(driverId);
      if (!wallet) {
        return res.status(404).json({ error: "Wallet not found" });
      }

      const currentBalance = parseFloat(wallet.balance);
      const withdrawAmount = parseFloat(amount);

      if (withdrawAmount > currentBalance) {
        return res.status(400).json({ error: "Insufficient balance" });
      }

      // Create transaction
      const transaction = await storage.createTransaction({
        driverId,
        type: "withdrawal",
        amount: amount.toString(),
        status: "completed",
        date: new Date().toLocaleDateString(),
        time: new Date().toLocaleTimeString(),
      });

      // Update wallet balance
      const newBalance = (currentBalance - withdrawAmount).toFixed(2);
      await storage.updateWallet(wallet.id, {
        balance: newBalance
      });

      res.json({
        success: true,
        transaction,
        newBalance
      });
    } catch (error) {
      res.status(400).json({ error: "Invalid request" });
    }
  });

  // ========== Transaction Routes ==========

  // Get transactions by driver
  app.get("/api/transactions/driver/:driverId", async (req, res) => {
    try {
      const { driverId } = req.params;
      const transactions = await storage.getTransactionsByDriver(driverId);

      res.json(transactions);
    } catch (error) {
      res.status(400).json({ error: "Invalid request" });
    }
  });

  // Create transaction
  app.post("/api/transactions", async (req, res) => {
    try {
      const transaction = await storage.createTransaction(req.body);
      res.json(transaction);
    } catch (error) {
      res.status(400).json({ error: "Invalid transaction data" });
    }
  });

  const httpServer = createServer(app);

  return httpServer;
}

shared/schema.ts.content:
import { sql } from "drizzle-orm";
import { pgTable, text, varchar, integer, timestamp, decimal, boolean } from "drizzle-orm/pg-core";
import { createInsertSchema } from "drizzle-zod";
import { z } from "zod";

// Driver Schema
export const drivers = pgTable("drivers", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  fullName: text("full_name").notNull(),
  email: text("email").notNull().unique(),
  phoneNumber: text("phone_number").notNull(),
  password: text("password").notNull(),
  country: text("country"),
  idCardNumber: text("id_card_number"),
  address: text("address"),
  workingHours: text("working_hours"),
  bankName: text("bank_name"),
  accountHolderName: text("account_holder_name"),
  accountNumber: text("account_number"),
  preferredPaymentMethod: text("preferred_payment_method"),
  secondaryContactNumber: text("secondary_contact_number"),
  isEmailVerified: boolean("is_email_verified").default(false),
  createdAt: timestamp("created_at").defaultNow(),
});

// Order Schema
export const orders = pgTable("orders", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  orderNumber: text("order_number").notNull(),
  driverId: varchar("driver_id").references(() => drivers.id),
  customerName: text("customer_name").notNull(),
  customerLocation: text("customer_location").notNull(),
  pickupLocation: text("pickup_location").notNull(),
  dropoffLocation: text("dropoff_location").notNull(),
  orderType: text("order_type").notNull(),
  status: text("status").notNull().default("pending"), // pending, active, completed, canceled
  deliveryTime: text("delivery_time"),
  orderDate: text("order_date").notNull(),
  createdAt: timestamp("created_at").defaultNow(),
});

// Transaction Schema
export const transactions = pgTable("transactions", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  driverId: varchar("driver_id").references(() => drivers.id),
  type: text("type").notNull(), // withdrawal, cash_received
  amount: decimal("amount", { precision: 10, scale: 2 }).notNull(),
  status: text("status").notNull(), // completed, confirmed, pending
  date: text("date").notNull(),
  time: text("time").notNull(),
  createdAt: timestamp("created_at").defaultNow(),
});

// Wallet Schema
export const wallets = pgTable("wallets", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  driverId: varchar("driver_id").references(() => drivers.id).unique(),
  balance: decimal("balance", { precision: 10, scale: 2 }).notNull().default("0"),
  cardNumber: text("card_number"),
  bankName: text("bank_name"),
  expiryDate: text("expiry_date"),
  cvv: text("cvv"),
});

// Insert Schemas
export const insertDriverSchema = createInsertSchema(drivers).omit({
  id: true,
  isEmailVerified: true,
  createdAt: true,
});

export const insertOrderSchema = createInsertSchema(orders).omit({
  id: true,
  createdAt: true,
});

export const insertTransactionSchema = createInsertSchema(transactions).omit({
  id: true,
  createdAt: true,
});

export const insertWalletSchema = createInsertSchema(wallets).omit({
  id: true,
});

// Registration Step Schemas
export const registrationStep1Schema = z.object({
  fullName: z.string().min(2, "Full name is required"),
  email: z.string().email("Invalid email address"),
  phoneNumber: z.string().min(10, "Phone number must be at least 10 digits"),
  password: z.string().min(6, "Password must be at least 6 characters"),
  confirmPassword: z.string(),
}).refine((data) => data.password === data.confirmPassword, {
  message: "Passwords don't match",
  path: ["confirmPassword"],
});

export const registrationStep2Schema = z.object({
  country: z.string().min(2, "Country is required"),
  idCardNumber: z.string().min(5, "ID Card number is required"),
  address: z.string().min(5, "Address is required"),
  workingHours: z.string().min(1, "Working hours are required"),
  bankName: z.string().min(2, "Bank name is required"),
  accountHolderName: z.string().min(2, "Account holder name is required"),
  accountNumber: z.string().min(5, "Account number is required"),
  preferredPaymentMethod: z.string().min(2, "Payment method is required"),
  secondaryContactNumber: z.string().optional(),
});

export const loginSchema = z.object({
  emailOrPhone: z.string().min(1, "Email or phone number is required"),
  password: z.string().min(1, "Password is required"),
});

export const emailVerificationSchema = z.object({
  email: z.string().email("Invalid email address"),
});

export const otpVerificationSchema = z.object({
  code: z.string().length(4, "Code must be 4 digits"),
});

// Admin Country Options Schemas
export const optionBankSchema = z.object({
  name: z.string().min(2, "Bank name is required"),
});

export const optionWorkingHourSchema = z.object({
  value: z.string().min(2, "Working hour is required"),
});

export const countryQuerySchema = z.object({
  country: z.string().min(2, "Country is required"),
});

// Types
export type Driver = typeof drivers.$inferSelect;
export type InsertDriver = z.infer<typeof insertDriverSchema>;
export type Order = typeof orders.$inferSelect;
export type InsertOrder = z.infer<typeof insertOrderSchema>;
export type Transaction = typeof transactions.$inferSelect;
export type InsertTransaction = z.infer<typeof insertTransactionSchema>;
export type Wallet = typeof wallets.$inferSelect;
export type InsertWallet = z.infer<typeof insertWalletSchema>;
export type RegistrationStep1 = z.infer<typeof registrationStep1Schema>;
export type RegistrationStep2 = z.infer<typeof registrationStep2Schema>;
export type LoginData = z.infer<typeof loginSchema>;
export type EmailVerification = z.infer<typeof emailVerificationSchema>;
export type OtpVerification = z.infer<typeof otpVerificationSchema>;
export type OptionBank = z.infer<typeof optionBankSchema>;
export type OptionWorkingHour = z.infer<typeof optionWorkingHourSchema>;

