import { 
  type Driver, type InsertDriver,
  type Order, type InsertOrder,
  type Transaction, type InsertTransaction,
  type Wallet, type InsertWallet
} from "@shared/schema";
import { randomUUID } from "crypto";

export interface IStorage {
  // Driver methods
  getDriver(id: string): Promise<Driver | undefined>;
  getDriverByEmail(email: string): Promise<Driver | undefined>;
  getDriverByEmailOrPhone(emailOrPhone: string): Promise<Driver | undefined>;
  createDriver(driver: Omit<InsertDriver, 'isEmailVerified' | 'createdAt'>): Promise<Driver>;
  updateDriver(id: string, driver: Partial<Driver>): Promise<Driver | undefined>;

  // Order methods
  getOrder(id: string): Promise<Order | undefined>;
  getAllOrders(): Promise<Order[]>;
  getOrdersByStatus(status: string): Promise<Order[]>;
  getOrdersByDriver(driverId: string): Promise<Order[]>;
  createOrder(order: Omit<InsertOrder, 'createdAt'>): Promise<Order>;
  updateOrder(id: string, order: Partial<Order>): Promise<Order | undefined>;

  // Transaction methods
  getTransaction(id: string): Promise<Transaction | undefined>;
  getTransactionsByDriver(driverId: string): Promise<Transaction[]>;
  createTransaction(transaction: Omit<InsertTransaction, 'createdAt'>): Promise<Transaction>;

  // Wallet methods
  getWallet(id: string): Promise<Wallet | undefined>;
  getWalletByDriver(driverId: string): Promise<Wallet | undefined>;
  createWallet(wallet: InsertWallet): Promise<Wallet>;
  updateWallet(id: string, wallet: Partial<Wallet>): Promise<Wallet | undefined>;

  // Country Options methods
  listCountries(): Promise<string[]>;
  getOptions(country: string): Promise<{ banks: string[]; workingHours: string[] } | undefined>;
  addBank(country: string, bank: string): Promise<{ banks: string[]; workingHours: string[] }>;
  removeBank(country: string, bank: string): Promise<{ banks: string[]; workingHours: string[] }>;
  addWorkingHour(country: string, hour: string): Promise<{ banks: string[]; workingHours: string[] }>;
  removeWorkingHour(country: string, hour: string): Promise<{ banks: string[]; workingHours: string[] }>;
}

export class MemStorage implements IStorage {
  private drivers: Map<string, Driver>;
  private orders: Map<string, Order>;
  private transactions: Map<string, Transaction>;
  private wallets: Map<string, Wallet>;
  private countryOptions: Map<string, { banks: string[]; workingHours: string[] }>;

  constructor() {
    this.drivers = new Map();
    this.orders = new Map();
    this.transactions = new Map();
    this.wallets = new Map();
    this.countryOptions = new Map();

    // Initialize with mock data
    this.initializeMockData();
  }

  private initializeMockData() {
    // Initialize country options
    this.countryOptions.set("Indonesia", {
      banks: ["BCA", "BNI", "BRI", "Mandiri", "CIMB Niaga", "Permata"],
      workingHours: ["08:00-17:00", "09:00-18:00", "07:00-15:00", "13:00-21:00"],
    });
    this.countryOptions.set("Malaysia", {
      banks: ["Maybank", "CIMB", "Public Bank", "Hong Leong Bank", "RHB"],
      workingHours: ["08:30-17:30", "09:00-18:00"],
    });
    this.countryOptions.set("Singapore", {
      banks: ["DBS", "OCBC", "UOB", "Standard Chartered"],
      workingHours: ["09:00-18:00", "10:00-19:00"],
    });
    this.countryOptions.set("Thailand", {
      banks: ["Bangkok Bank", "Kasikorn Bank", "Krungsri", "SCB"],
      workingHours: ["09:00-17:00", "10:00-18:00"],
    });
    this.countryOptions.set("Philippines", {
      banks: ["BDO", "BPI", "Metrobank", "Landbank", "PNB"],
      workingHours: ["08:00-17:00", "09:00-18:00"],
    });
    // Create a test driver
    const testDriver: Driver = {
      id: "driver1",
      fullName: "Shah Hussain",
      email: "shah@fuelfriend.com",
      phoneNumber: "+1234567890",
      password: "password123",
      country: "Indonesia",
      idCardNumber: "1234567890",
      address: "123 Main St, Tennessee",
      workingHours: "9:00AM-5:00PM",
      bankName: "National Bank",
      accountHolderName: "Shah Hussain",
      accountNumber: "1234567890",
      preferredPaymentMethod: "Paypal",
      secondaryContactNumber: null,
      isEmailVerified: true,
      createdAt: new Date(),
    };
    this.drivers.set(testDriver.id, testDriver);

    // Create test wallet
    const testWallet: Wallet = {
      id: "wallet1",
      driverId: "driver1",
      balance: "7284.00",
      cardNumber: "5000 0000 0000 0000",
      bankName: "BANK NAME",
      expiryDate: "10/28",
      cvv: "123",
    };
    this.wallets.set(testWallet.id, testWallet);

    // Create test orders
    const testOrders: Order[] = [
      {
        id: "order1",
        orderNumber: "Order #1",
        driverId: null,
        customerName: "John Doe",
        customerLocation: "Tennessee",
        pickupLocation: "Shell Station- Abc Town",
        dropoffLocation: "Shell Station- Abc Town",
        orderType: "Fuel delivery",
        status: "pending",
        orderDate: "25/03/2025",
        deliveryTime: null,
        createdAt: new Date(),
      },
      {
        id: "order2",
        orderNumber: "Order #123",
        driverId: null,
        customerName: "Jane Smith",
        customerLocation: "Tennessee",
        pickupLocation: "Shell Station- Tennessee",
        dropoffLocation: "Shell Station-Tennessee",
        orderType: "Fuel, Groceries delivery",
        status: "pending",
        orderDate: "25/03/2025",
        deliveryTime: null,
        createdAt: new Date(),
      },
      {
        id: "order3",
        orderNumber: "Order #124",
        driverId: "driver1",
        customerName: "Mike Johnson",
        customerLocation: "Tennessee",
        pickupLocation: "Shell Station- Tennessee",
        dropoffLocation: "Shell Station-Tennessee",
        orderType: "Fuel",
        status: "active",
        orderDate: "25/03/2025",
        deliveryTime: "Before 8:30 PM",
        createdAt: new Date(),
      },
      {
        id: "order4",
        orderNumber: "Order #125",
        driverId: "driver1",
        customerName: "Sarah Williams",
        customerLocation: "Tennessee",
        pickupLocation: "Shell Station- Tennessee",
        dropoffLocation: "Shell Station-Tennessee",
        orderType: "Fuel, Groceries delivery",
        status: "active",
        orderDate: "25/03/2025",
        deliveryTime: "Before 9:00 PM",
        createdAt: new Date(),
      },
      {
        id: "order5",
        orderNumber: "Order #126",
        driverId: "driver1",
        customerName: "Alice Brown",
        customerLocation: "Tennessee",
        pickupLocation: "Shell Station- Tennessee",
        dropoffLocation: "Shell Station-Tennessee",
        orderType: "Fuel, Groceries delivery",
        status: "completed",
        orderDate: "25/03/2025",
        deliveryTime: null,
        createdAt: new Date(),
      },
    ];
    testOrders.forEach(order => this.orders.set(order.id, order));

    // Create test transactions
    const testTransactions: Transaction[] = [
      {
        id: "txn1",
