      },
    ];
    testTransactions.forEach(txn => this.transactions.set(txn.id, txn));
  }

  // Driver methods
  async getDriver(id: string): Promise<Driver | undefined> {
    return this.drivers.get(id);
  }

  async getDriverByEmail(email: string): Promise<Driver | undefined> {
    return Array.from(this.drivers.values()).find(
      (driver) => driver.email === email
    );
  }

  async getDriverByEmailOrPhone(emailOrPhone: string): Promise<Driver | undefined> {
    return Array.from(this.drivers.values()).find(
      (driver) => driver.email === emailOrPhone || driver.phoneNumber === emailOrPhone
    );
  }

  async createDriver(insertDriver: Omit<InsertDriver, 'isEmailVerified' | 'createdAt'>): Promise<Driver> {
    const id = randomUUID();
    const driver: Driver = { 
      ...insertDriver, 
      id,
      isEmailVerified: false,
      createdAt: new Date()
    };
    this.drivers.set(id, driver);

    // Create wallet for new driver
    const walletId = randomUUID();
    const wallet: Wallet = {
      id: walletId,
      driverId: id,
      balance: "0.00",
      cardNumber: null,
      bankName: null,
      expiryDate: null,
      cvv: null,
    };
    this.wallets.set(walletId, wallet);

    return driver;
  }

  async updateDriver(id: string, updates: Partial<Driver>): Promise<Driver | undefined> {
    const driver = this.drivers.get(id);
    if (!driver) return undefined;

    const updatedDriver = { ...driver, ...updates };
    this.drivers.set(id, updatedDriver);
    return updatedDriver;
  }

  // Order methods
  async getOrder(id: string): Promise<Order | undefined> {
    return this.orders.get(id);
  }

  async getAllOrders(): Promise<Order[]> {
    return Array.from(this.orders.values());
  }

  async getOrdersByStatus(status: string): Promise<Order[]> {
    return Array.from(this.orders.values()).filter(
      (order) => order.status === status
    );
  }

  async getOrdersByDriver(driverId: string): Promise<Order[]> {
    return Array.from(this.orders.values()).filter(
      (order) => order.driverId === driverId
    );
  }

  async createOrder(insertOrder: Omit<InsertOrder, 'createdAt'>): Promise<Order> {
    const id = randomUUID();
    const order: Order = { 
      ...insertOrder, 
      id,
      createdAt: new Date()
    };
    this.orders.set(id, order);
    return order;
  }

  async updateOrder(id: string, updates: Partial<Order>): Promise<Order | undefined> {
    const order = this.orders.get(id);
    if (!order) return undefined;

    const updatedOrder = { ...order, ...updates };
    this.orders.set(id, updatedOrder);
    return updatedOrder;
  }

  // Transaction methods
  async getTransaction(id: string): Promise<Transaction | undefined> {
    return this.transactions.get(id);
  }

  async getTransactionsByDriver(driverId: string): Promise<Transaction[]> {
    return Array.from(this.transactions.values()).filter(
      (transaction) => transaction.driverId === driverId
    );
  }

  async createTransaction(insertTransaction: Omit<InsertTransaction, 'createdAt'>): Promise<Transaction> {
    const id = randomUUID();
    const transaction: Transaction = { 
      ...insertTransaction, 
      id,
      createdAt: new Date()
    };
    this.transactions.set(id, transaction);
    return transaction;
  }

  // Wallet methods
  async getWallet(id: string): Promise<Wallet | undefined> {
    return this.wallets.get(id);
  }

  async getWalletByDriver(driverId: string): Promise<Wallet | undefined> {
    return Array.from(this.wallets.values()).find(
      (wallet) => wallet.driverId === driverId
    );
  }

  async createWallet(insertWallet: InsertWallet): Promise<Wallet> {
    const id = randomUUID();
    const wallet: Wallet = { ...insertWallet, id };
    this.wallets.set(id, wallet);
    return wallet;
  }

  async updateWallet(id: string, updates: Partial<Wallet>): Promise<Wallet | undefined> {
    const wallet = this.wallets.get(id);
    if (!wallet) return undefined;

    const updatedWallet = { ...wallet, ...updates };
    this.wallets.set(id, updatedWallet);
    return updatedWallet;
  }

  // Country Options methods
  async listCountries(): Promise<string[]> {
    return Array.from(this.countryOptions.keys());
  }

  async getOptions(country: string): Promise<{ banks: string[]; workingHours: string[] } | undefined> {
    const entry = this.countryOptions.get(country);
    if (!entry) return undefined;
    // return copies to avoid external mutation
    return { banks: [...entry.banks], workingHours: [...entry.workingHours] };
  }

  async addBank(country: string, bank: string): Promise<{ banks: string[]; workingHours: string[] }> {
    const entry = this.countryOptions.get(country);
    if (!entry) {
      const newEntry = { banks: [bank], workingHours: [] };
      this.countryOptions.set(country, newEntry);
      return { banks: [...newEntry.banks], workingHours: [...newEntry.workingHours] };
    }
    if (!entry.banks.includes(bank)) entry.banks.push(bank);
    return { banks: [...entry.banks], workingHours: [...entry.workingHours] };
  }

  async removeBank(country: string, bank: string): Promise<{ banks: string[]; workingHours: string[] }> {
    const entry = this.countryOptions.get(country) || { banks: [], workingHours: [] };
    entry.banks = entry.banks.filter((b) => b !== bank);
    this.countryOptions.set(country, entry);
    return { banks: [...entry.banks], workingHours: [...entry.workingHours] };
  }

  async addWorkingHour(country: string, hour: string): Promise<{ banks: string[]; workingHours: string[] }> {
    const entry = this.countryOptions.get(country);
    if (!entry) {
      const newEntry = { banks: [], workingHours: [hour] };
      this.countryOptions.set(country, newEntry);
      return { banks: [...newEntry.banks], workingHours: [...newEntry.workingHours] };
    }
    if (!entry.workingHours.includes(hour)) entry.workingHours.push(hour);
    return { banks: [...entry.banks], workingHours: [...entry.workingHours] };
  }

  async removeWorkingHour(country: string, hour: string): Promise<{ banks: string[]; workingHours: string[] }> {
    const entry = this.countryOptions.get(country) || { banks: [], workingHours: [] };
    entry.workingHours = entry.workingHours.filter((h) => h !== hour);
    this.countryOptions.set(country, entry);
    return { banks: [...entry.banks], workingHours: [...entry.workingHours] };
  }
}

export const storage = new MemStorage();

