import { useEffect, useState } from "react";
import { useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { ArrowLeft } from "lucide-react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { registrationStep1Schema, registrationStep2Schema, type RegistrationStep1, type RegistrationStep2 } from "@shared/schema";
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { StepIndicator } from "@/components/StepIndicator";
import { Card } from "@/components/ui/card";
import { useToast } from "@/hooks/use-toast";
import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from "@/components/ui/select";

export default function Register() {
  const [, setLocation] = useLocation();
  const { toast } = useToast();
  const [currentStep, setCurrentStep] = useState(1);
  const [step1Data, setStep1Data] = useState<RegistrationStep1 | null>(null);
  const [step2Data, setStep2Data] = useState<RegistrationStep2 | null>(null);
  // Country will be controlled by form2; no separate state needed

  const COUNTRY_OPTIONS = [
    "Indonesia",
    "Malaysia",
    "Singapore",
    "Thailand",
    "Philippines",
  ];

  const BANK_OPTIONS: Record<string, string[]> = {
    Indonesia: ["BCA", "BNI", "BRI", "Mandiri", "CIMB Niaga", "Permata"],
    Malaysia: ["Maybank", "CIMB", "Public Bank", "Hong Leong Bank", "RHB"],
    Singapore: ["DBS", "OCBC", "UOB", "Standard Chartered"],
    Thailand: ["Bangkok Bank", "Kasikorn Bank", "Krungsri", "SCB"],
    Philippines: ["BDO", "BPI", "Metrobank", "Landbank", "PNB"],
  };

  const WORKING_HOURS_OPTIONS: Record<string, string[]> = {
    Indonesia: ["08:00-17:00", "09:00-18:00", "07:00-15:00", "13:00-21:00"],
    Malaysia: ["08:30-17:30", "09:00-18:00"],
    Singapore: ["09:00-18:00", "10:00-19:00"],
    Thailand: ["09:00-17:00", "10:00-18:00"],
    Philippines: ["08:00-17:00", "09:00-18:00"],
  };

  const form1 = useForm<RegistrationStep1>({
    resolver: zodResolver(registrationStep1Schema),
    defaultValues: {
      fullName: "",
      email: "",
      phoneNumber: "",
      password: "",
      confirmPassword: "",
    },
  });

  const form2 = useForm<RegistrationStep2>({
    resolver: zodResolver(registrationStep2Schema),
    defaultValues: {
      country: "",
      idCardNumber: "",
      address: "",
      workingHours: "",
      bankName: "",
      accountHolderName: "",
      accountNumber: "",
      preferredPaymentMethod: "",
      secondaryContactNumber: "",
    },
  });

  const selectedCountry = form2.watch("country");
  const [bankOptions, setBankOptions] = useState<string[]>([]);
  const [hoursOptions, setHoursOptions] = useState<string[]>([]);

  useEffect(() => {
    if (!selectedCountry) {
      setBankOptions([]);
      setHoursOptions([]);
      return;
    }

    const controller = new AbortController();
    const fetchOptions = async () => {
      try {
        const resp = await fetch(`/api/options?country=${encodeURIComponent(selectedCountry)}`, { signal: controller.signal });
        const data = await resp.json();
        setBankOptions(data.bankOptions ?? (BANK_OPTIONS[selectedCountry] || []));
        setHoursOptions(data.workingHoursOptions ?? (WORKING_HOURS_OPTIONS[selectedCountry] || []));
      } catch (_err) {
        // Fallback ke opsi lokal jika API gagal
        setBankOptions(BANK_OPTIONS[selectedCountry] || []);
        setHoursOptions(WORKING_HOURS_OPTIONS[selectedCountry] || []);
      }

      // Reset pilihan dependent agar tidak mismatch ketika negara berubah
      form2.setValue("bankName", "");
      form2.setValue("workingHours", "");
    };

    fetchOptions();
    return () => controller.abort();
  }, [selectedCountry]);

  const onStep1Submit = (data: RegistrationStep1) => {
    setStep1Data(data);
    setCurrentStep(2);
  };

  const onStep2Submit = (data: RegistrationStep2) => {
    setStep2Data(data);
    setCurrentStep(3);
  };

  const handleCreateAccount = async () => {
    if (!step1Data || !step2Data) return;

    try {
      const response = await fetch("/api/auth/register", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ step1: step1Data, step2: step2Data }),
      });

      const result = await response.json();

      if (!response.ok) {
        throw new Error(result.error || "Failed to create account");
      }

      localStorage.setItem("driverId", result.driver.id);
      localStorage.setItem("driverEmail", result.driver.email);

      toast({
        title: "Success!",
        description: "Account created successfully",
      });
      setLocation("/face-verification");
    } catch (error) {
      toast({
        title: "Error",
        description: error instanceof Error ? error.message : "Failed to create account",
        variant: "destructive",
      });
    }
  };

  return (
    <div className="min-h-screen bg-background p-3 pb-safe">
      <div className="w-full max-w-sm mx-auto">
        <Button
          variant="ghost"
          size="icon"
          onClick={() => currentStep > 1 ? setCurrentStep(currentStep - 1) : setLocation("/login")}
          className="mb-3"
