import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Phone, MessageCircle, MapPin } from "lucide-react";
import type { Order } from "@shared/schema";

interface OrderCardProps {
  order: Order;
  onAccept?: (orderId: string) => void;
  onCancel?: (orderId: string) => void;
  onCall?: (orderId: string) => void;
  onMessage?: (orderId: string) => void;
  onTrack?: (orderId: string) => void;
}

export function OrderCard({ order, onAccept, onCancel, onCall, onMessage, onTrack }: OrderCardProps) {
  const getStatusColor = (status: string) => {
    switch (status) {
      case "pending":
        return "bg-[hsl(var(--pending))] text-[hsl(var(--pending-foreground))]";
      case "active":
        return "bg-[hsl(var(--active))] text-[hsl(var(--active-foreground))]";
      case "completed":
        return "bg-[hsl(var(--completed))] text-[hsl(var(--completed-foreground))]";
      case "canceled":
        return "bg-[hsl(var(--canceled))] text-[hsl(var(--canceled-foreground))]";
      default:
        return "bg-muted text-muted-foreground";
    }
  };

  return (
    <Card className="relative p-4 space-y-3 border-card-border shadow-sm rounded-xl hover-elevate">
      <Badge 
        className={`absolute top-4 right-4 rounded-full px-3 py-1 text-xs font-medium capitalize ${getStatusColor(order.status)}`}
      >
        {order.status}
      </Badge>

      <div className="pr-20">
        <h3 className="text-base font-bold text-foreground">{order.orderNumber}</h3>
        <p className="text-xs text-muted-foreground mt-1">{order.orderDate}</p>
      </div>

      <div className="space-y-2 text-sm">
        <div className="flex items-start gap-2">
          <span className="text-muted-foreground min-w-[70px]">Pickup:</span>
          <span className="text-foreground font-medium">{order.pickupLocation}</span>
        </div>
        <div className="flex items-start gap-2">
          <span className="text-muted-foreground min-w-[70px]">Drop off:</span>
          <span className="text-foreground font-medium">{order.dropoffLocation}</span>
        </div>
        <div className="flex items-start gap-2">
          <span className="text-muted-foreground min-w-[70px]">Order type:</span>
          <span className="text-foreground font-medium">{order.orderType}</span>
        </div>
      </div>

      {order.status === "pending" && onAccept && onCancel && (
        <div className="grid grid-cols-2 gap-3 pt-2">
          <Button
            variant="outline"
            onClick={() => onCancel(order.id)}
            data-testid={`button-cancel-${order.id}`}
            className="w-full"
          >
            Cancel Request
          </Button>
          <Button
            onClick={() => onAccept(order.id)}
            data-testid={`button-accept-${order.id}`}
            className="w-full"
          >
            Accept Request
          </Button>
        </div>
      )}

      {order.status === "active" && onCall && onMessage && onTrack && (
        <div className="grid grid-cols-3 gap-2 pt-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => onCall(order.id)}
            data-testid={`button-call-${order.id}`}
            className="flex items-center gap-1"
          >
            <Phone className="w-4 h-4" />
            Call
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={() => onMessage(order.id)}
            data-testid={`button-message-${order.id}`}
            className="flex items-center gap-1"
          >
            <MessageCircle className="w-4 h-4" />
            Message
          </Button>
          <Button
            size="sm"
            onClick={() => onTrack(order.id)}
            data-testid={`button-track-${order.id}`}
            className="flex items-center gap-1"
          >
            <MapPin className="w-4 h-4" />
            Track
          </Button>
        </div>
      )}
    </Card>
  );
}

