import { Link, useLocation } from "wouter";
import { Home, ClipboardList, Wallet, Settings } from "lucide-react";

export function BottomNav() {
  const [location] = useLocation();

  const navItems = [
    { path: "/dashboard", icon: Home, label: "Home", testId: "nav-home" },
    { path: "/orders", icon: ClipboardList, label: "My Orders", testId: "nav-orders" },
    { path: "/wallet", icon: Wallet, label: "Wallet", testId: "nav-wallet" },
    { path: "/settings", icon: Settings, label: "Settings", testId: "nav-settings" },
  ];

  return (
    <nav className="fixed bottom-0 left-0 right-0 bg-card border-t border-card-border h-16 flex items-center justify-around z-50 safe-area-inset-bottom">
      {navItems.map((item) => {
        const isActive = location === item.path;
        const Icon = item.icon;

        return (
          <Link
            key={item.path}
            href={item.path}
            data-testid={item.testId}
          >
            <a className={`flex flex-col items-center justify-center gap-1 px-4 py-2 transition-colors ${
              isActive ? "text-primary" : "text-muted-foreground"
            }`}>
              <Icon className="w-5 h-5" strokeWidth={isActive ? 2.5 : 2} />
              <span className="text-xs font-medium">{item.label}</span>
            </a>
          </Link>
        );
      })}
    </nav>
  );
}

