import { useEffect, useRef, useState } from "react";
import { useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Fuel } from "lucide-react";
import { FcGoogle } from "react-icons/fc";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { loginSchema, type LoginData } from "@shared/schema";
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { useToast } from "@/hooks/use-toast";

export default function Login() {
  const [, setLocation] = useLocation();
  const { toast } = useToast();
  const [isLoading, setIsLoading] = useState(false);
  const topLottieRef = useRef<HTMLDivElement>(null);
  const bottomLottieRef = useRef<HTMLDivElement>(null);

  const form = useForm<LoginData>({
    resolver: zodResolver(loginSchema),
    defaultValues: {
      emailOrPhone: "",
      password: "",
    },
  });

  const onSubmit = async (data: LoginData) => {
    setIsLoading(true);
    try {
      const response = await fetch("/api/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data),
      });

      const result = await response.json();

      if (!response.ok) {
        throw new Error(result.error || "Invalid credentials");
      }

      localStorage.setItem("driverId", result.driver.id);
      localStorage.setItem("driverEmail", result.driver.email);

      toast({
        title: "Success!",
        description: "Logged in successfully",
      });
      setLocation("/dashboard");
    } catch (error) {
      toast({
        title: "Error",
        description: error instanceof Error ? error.message : "Invalid credentials",
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleGoogleLogin = async () => {
    setIsLoading(true);
    try {
      const resp = await fetch("/api/auth/google/url");
      const json = await resp.json();
      if (!resp.ok || !json.url) {
        throw new Error(json.error || "Google auth unavailable");
      }
      window.location.href = json.url;
    } catch (error) {
      toast({
        title: "Error",
        description: error instanceof Error ? error.message : "Failed to start Google login",
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  // Muat animasi Lottie ke rectangles (atas & bawah)
  useEffect(() => {
    const lottie: any = (window as any).lottie;
    if (!lottie) return;

    let animTop: any | null = null;
    let animBottom: any | null = null;

    if (topLottieRef.current) {
      animTop = lottie.loadAnimation({
        container: topLottieRef.current,
        renderer: "svg",
        loop: true,
        autoplay: true,
        path: "/lottie/ambient-circles.json",
        name: "login-rect-top",
        rendererSettings: { preserveAspectRatio: "xMidYMid slice" },
      });
      animTop.setSpeed?.(0.6);
    }

    if (bottomLottieRef.current) {
      animBottom = lottie.loadAnimation({
        container: bottomLottieRef.current,
        renderer: "svg",
        loop: true,
        autoplay: true,
        path: "/lottie/ambient-circles.json",
        name: "login-rect-bottom",
        rendererSettings: { preserveAspectRatio: "xMidYMid slice" },
      });
      animBottom.setSpeed?.(0.5);
      animBottom.setDirection?.(-1);
    }

    return () => {
      animTop?.destroy?.();
      animBottom?.destroy?.();
    };
  }, []);

  return (
    <div className="min-h-screen bg-background flex flex-col relative overflow-hidden">
      {/* Decorative rectangles (top & bottom) */}
      <div
        aria-hidden
        className="absolute inset-x-0 top-0 h-[20vh] z-0 pointer-events-none select-none"
        style={{
          backgroundImage: "url(/Rectangle%203364.svg)",
          backgroundRepeat: "no-repeat",
          backgroundSize: "cover",
          backgroundPosition: "top center",
        }}
      >
        {/* Lottie overlay container (top rectangle) */}
        <div
          ref={topLottieRef}
          className="absolute inset-0 opacity-80"
          style={{ mixBlendMode: "screen" }}
        />
      </div>
      <div
        aria-hidden
        className="absolute inset-x-0 bottom-0 h-[20vh] z-0 pointer-events-none select-none"
        style={{
          backgroundImage: "url(/Rectangle%203365.png)",
          backgroundRepeat: "no-repeat",
          backgroundSize: "cover",
          backgroundPosition: "bottom center",
          transform: "translateY(-56px)",
        }}
      >
        {/* Lottie overlay container (bottom rectangle) */}
        <div
          ref={bottomLottieRef}
          className="absolute inset-0 opacity-60"
          style={{ mixBlendMode: "screen" }}
        />
      </div>

      <div className="w-full max-w-sm mx-auto flex-1 flex flex-col relative z-10 pt-16 pb-16 px-4" style={{ transform: "translateY(-56px)" }}>
        <div className="flex flex-col items-center text-center mb-6">
          <img src="/logo.png" alt="Logo" className="w-24 h-24 object-contain" />
        </div>

        <Form {...form}>
          <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
            <FormField
              control={form.control}
              name="emailOrPhone"
              render={({ field }) => (
                <FormItem>
                  <FormLabel className="text-xs font-medium">Email or phone number</FormLabel>
                  <FormControl>
                    <Input
                      {...field}
                      type="text"
                      placeholder="Enter email or phone"
                      className="h-10 text-sm"
                      data-testid="input-email-phone"
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="password"
              render={({ field }) => (
                <FormItem>
                  <FormLabel className="text-xs font-medium">Password</FormLabel>
                  <FormControl>
                    <Input
                      {...field}
                      type="password"
                      placeholder="Enter password"
                      className="h-10 text-sm"
                      data-testid="input-password"
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <div className="text-right">
              <Button
                type="button"
                variant="link"
                className="text-primary p-0 h-auto font-normal"
                onClick={() => setLocation("/email-verification")}
                data-testid="link-forgot-password"
              >
                Forgotten Password
              </Button>
            </div>

            <Button
              type="submit"
              className="w-full h-10 text-sm font-semibold"
              disabled={isLoading}
              data-testid="button-submit-login"
            >
              {isLoading ? "Logging in..." : "Log In"}
            </Button>

            <div className="relative">
              <div className="absolute inset-0 flex items-center">
                <div className="w-full border-t border-border"></div>
              </div>
              <div className="relative flex justify-center text-sm">
                <span className="px-4 bg-background text-muted-foreground">Or</span>
              </div>
            </div>

            <Button
              type="button"
              variant="outline"
              className="w-full h-10 text-sm font-semibold flex items-center justify-center gap-2"
              onClick={handleGoogleLogin}
              data-testid="button-google-login"
            >
              <FcGoogle className="w-4 h-4" />
              Continue with Google
            </Button>
          </form>
        </Form>

        <div className="mt-6 text-center">
          <span className="text-sm text-muted-foreground">Don't have an account? </span>
          <Button
            variant="link"
            className="text-primary p-0 h-auto text-sm font-semibold"
            onClick={() => setLocation("/register")}
            data-testid="link-signup"
          >
            Sign up
          </Button>
        </div>
      </div>
    </div>
  );
}

