import { useLocation } from "wouter";
import { BottomNav } from "@/components/BottomNav";
import { OrderCard } from "@/components/OrderCard";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Skeleton } from "@/components/ui/skeleton";
import { useToast } from "@/hooks/use-toast";
import { useOrders, useAcceptOrder, useCancelOrder } from "@/hooks/useOrders";

export default function AllOrders() {
  const [, setLocation] = useLocation();
  const { toast } = useToast();

  const driverId = localStorage.getItem("driverId") || "driver1";

  const { data: pendingOrders = [], isLoading: isLoadingPending } = useOrders("pending");
  const { data: activeOrders = [], isLoading: isLoadingActive } = useOrders("active", driverId);
  const { data: completedOrders = [], isLoading: isLoadingCompleted } = useOrders("completed", driverId);

  const acceptOrderMutation = useAcceptOrder();
  const cancelOrderMutation = useCancelOrder();

  const handleAcceptOrder = async (orderId: string) => {
    try {
      await acceptOrderMutation.mutateAsync({ orderId, driverId });
      toast({
        title: "Order Accepted!",
        description: "You have accepted the order",
      });
    } catch (error) {
      toast({
        title: "Error",
        description: "Failed to accept order",
        variant: "destructive",
      });
    }
  };

  const handleCancelOrder = async (orderId: string) => {
    try {
      await cancelOrderMutation.mutateAsync(orderId);
      toast({
        title: "Order Cancelled",
        description: "You have cancelled the order request",
      });
    } catch (error) {
      toast({
        title: "Error",
        description: "Failed to cancel order",
        variant: "destructive",
      });
    }
  };

  const handleCall = (orderId: string) => {
    toast({
      title: "Calling customer...",
    });
  };

  const handleMessage = (orderId: string) => {
    toast({
      title: "Opening messages...",
    });
  };

  const handleTrack = (orderId: string) => {
    setLocation(`/track-customer/${orderId}`);
  };

  return (
    <div className="min-h-screen bg-background pb-20">
      <div className="p-4">
        <h1 className="text-2xl font-bold text-foreground mb-6">All Orders</h1>

        <Tabs defaultValue="new" className="w-full">
          <TabsList className="grid w-full grid-cols-3 mb-6">
            <TabsTrigger value="new" data-testid="tab-new">New</TabsTrigger>
            <TabsTrigger value="active" data-testid="tab-active">Active</TabsTrigger>
            <TabsTrigger value="history" data-testid="tab-history">History</TabsTrigger>
          </TabsList>

          <TabsContent value="new" className="space-y-3 mt-0">
            {isLoadingPending ? (
              <>
                <Skeleton className="h-40 w-full rounded-xl" />
                <Skeleton className="h-40 w-full rounded-xl" />
                <Skeleton className="h-40 w-full rounded-xl" />
              </>
            ) : pendingOrders.length > 0 ? (
              pendingOrders.map((order) => (
                <OrderCard
                  key={order.id}
                  order={order}
                  onAccept={handleAcceptOrder}
                  onCancel={handleCancelOrder}
                />
              ))
            ) : (
              <p className="text-sm text-muted-foreground text-center py-8">No new orders</p>
            )}
          </TabsContent>

          <TabsContent value="active" className="space-y-3 mt-0">
            {isLoadingActive ? (
              <>
                <Skeleton className="h-40 w-full rounded-xl" />
                <Skeleton className="h-40 w-full rounded-xl" />
                <Skeleton className="h-40 w-full rounded-xl" />
              </>
            ) : activeOrders.length > 0 ? (
              activeOrders.map((order) => (
                <OrderCard
                  key={order.id}
                  order={order}
                  onCall={handleCall}
                  onMessage={handleMessage}
                  onTrack={handleTrack}
                />
              ))
            ) : (
              <p className="text-sm text-muted-foreground text-center py-8">No active orders</p>
            )}
          </TabsContent>

          <TabsContent value="history" className="space-y-3 mt-0">
            {isLoadingCompleted ? (
              <>
                <Skeleton className="h-40 w-full rounded-xl" />
                <Skeleton className="h-40 w-full rounded-xl" />
                <Skeleton className="h-40 w-full rounded-xl" />
              </>
            ) : completedOrders.length > 0 ? (
              completedOrders.map((order) => (
                <OrderCard key={order.id} order={order} />
              ))
            ) : (
              <p className="text-sm text-muted-foreground text-center py-8">No order history</p>
            )}
          </TabsContent>
        </Tabs>
      </div>

      <BottomNav />
    </div>
  );
}

