import { useQuery, useMutation } from "@tanstack/react-query";
import { queryClient, apiRequest } from "@/lib/queryClient";
import type { Order } from "@shared/schema";

export function useOrders(status?: string, driverId?: string) {
  const params = new URLSearchParams();
  if (status) params.append("status", status);
  if (driverId) params.append("driverId", driverId);

  const queryString = params.toString();
  const endpoint = `/api/orders${queryString ? `?${queryString}` : ""}`;

  return useQuery<Order[]>({
    queryKey: ["/api/orders", status, driverId],
    queryFn: async () => {
      const response = await fetch(endpoint);
      if (!response.ok) throw new Error("Failed to fetch orders");
      return response.json();
    },
  });
}

export function useOrder(id: string) {
  return useQuery<Order>({
    queryKey: ["/api/orders", id],
    queryFn: async () => {
      const response = await fetch(`/api/orders/${id}`);
      if (!response.ok) throw new Error("Failed to fetch order");
      return response.json();
    },
    enabled: !!id,
  });
}

export function useAcceptOrder() {
  return useMutation({
    mutationFn: async ({ orderId, driverId }: { orderId: string; driverId: string }) => {
      return apiRequest("POST", `/api/orders/${orderId}/accept`, { driverId });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/orders"] });
    },
  });
}

export function useCancelOrder() {
  return useMutation({
    mutationFn: async (orderId: string) => {
      return apiRequest("POST", `/api/orders/${orderId}/cancel`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/orders"] });
    },
  });
}

export function useCompleteOrder() {
  return useMutation({
    mutationFn: async (orderId: string) => {
      return apiRequest("POST", `/api/orders/${orderId}/complete`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/orders"] });
    },
  });
}
